 // Independent raw TIFF rational reader for the three APEX tags, before ExifTool ValueConv.
 static Dictionary<int,double> RawExifApex(byte[] jpeg) {
  int p=2;while(p<jpeg.Length){int marker=jpeg[p+1],size=jpeg[p+2]*256+jpeg[p+3];if(marker==225&&jpeg.AsSpan(p+4,6).SequenceEqual("Exif\0\0"u8))break;p+=size+2;}
  int b=p+10;bool little=jpeg[b]==73;uint U(int i,int n){uint v=0;for(int k=0;k<n;k++)v|=(uint)jpeg[b+i+k]<<(8*(little?k:n-1-k));return v;}
  var values=new Dictionary<int,double>();void Ifd(int i){int count=(int)U(i,2);for(int j=0;j<count;j++){int e=i+2+j*12,id=(int)U(e,2),type=(int)U(e+2,2),offset=(int)U(e+8,4);if(id==0x8769)Ifd(offset);if(id is 0x9201 or 0x9202 or 0x9205){double numerator=type==10?(int)U(offset,4):U(offset,4),denominator=type==10?(int)U(offset+4,4):U(offset+4,4);values[id]=numerator/denominator;}}}Ifd((int)U(4,4));return values;
 }
